// OpenCode plugin entry for the @PLUGIN@ bundle, generated by
// scripts/sync-plugins.sh from scripts/templates/opencode-index.js.
// It registers the bundle's skills/ and nothing else (no hooks, no tools).
//
// OpenCode 1.x calls every exported function as a plugin factory; `plugin`
// adds skills/ to the skill search paths through the config hook.
// OpenCode 2.x reads the default export's `id` and calls `setup(ctx)`, which
// adds each skill through the skill registry.

import { readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const skillsDir = join(dirname(fileURLToPath(import.meta.url)), "skills");

function field(front, key) {
  const match = front.match(new RegExp(`^${key}:[ \\t]*(.*?)[ \\t]*$`, "m"));
  if (!match) return "";
  const value = match[1];
  if (value.startsWith('"') && value.endsWith('"') && value.length > 1) {
    try {
      return JSON.parse(value);
    } catch {
      return value.slice(1, -1);
    }
  }
  if (value.startsWith("'") && value.endsWith("'") && value.length > 1) {
    return value.slice(1, -1).replace(/''/g, "'");
  }
  return value;
}

// Skills whose SKILL.md lacks a parseable name and description are skipped.
function readSkills() {
  let entries;
  try {
    entries = readdirSync(skillsDir, { withFileTypes: true });
  } catch {
    return [];
  }
  const skills = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const path = join(skillsDir, entry.name, "SKILL.md");
    let text;
    try {
      text = readFileSync(path, "utf8");
    } catch {
      continue;
    }
    const front = text.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);
    if (!front) continue;
    const name = field(front[1], "name");
    const description = field(front[1], "description");
    if (!name || !description) continue;
    skills.push({ id: name, name, description, path, content: text.slice(front[0].length) });
  }
  return skills;
}

export const plugin = async () => ({
  config: async (cfg) => {
    if (!cfg || Array.isArray(cfg.skills)) return;
    cfg.skills = cfg.skills ?? {};
    cfg.skills.paths = cfg.skills.paths ?? [];
    if (!cfg.skills.paths.includes(skillsDir)) cfg.skills.paths.push(skillsDir);
  },
});

export const setup = async (ctx) => {
  if (typeof ctx?.skill?.transform !== "function") return {};
  const skills = readSkills();
  try {
    await ctx.skill.transform((draft) => {
      for (const skill of skills) draft.add(skill);
    });
  } catch (error) {
    console.error(`@PLUGIN@: could not register skills: ${error?.message ?? error}`);
  }
};

export default { id: "@PLUGIN@", server: plugin, setup };
